  7	final class Graph {
  8	    private final List<List<Integer>> adjacencyList;
  9	
 10	    Graph(int vertexCount) {
 11	        if (vertexCount < 0) {
 12	            throw new IllegalArgumentException("Vertex count cannot be negative.");
 13	        }
 14	
 15	        adjacencyList = new ArrayList<>(vertexCount);
 16	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 17	            adjacencyList.add(new ArrayList<>());
 18	        }
 19	    }
 20	
 21	    int vertexCount() {
 22	        return adjacencyList.size();
 23	    }
 24	
 25	    void addUndirectedEdge(int from, int to) {
 26	        validateVertex(from);
 27	        validateVertex(to);
 28	
 29	        adjacencyList.get(from).add(to);
 30	        adjacencyList.get(to).add(from);
 31	    }
 32	
 33	    List<Integer> neighborsOf(int vertex) {
 34	        validateVertex(vertex);
 35	        return Collections.unmodifiableList(adjacencyList.get(vertex));
 36	    }
 37	
 38	    private void validateVertex(int vertex) {
 39	        if (vertex < 0 || vertex >= adjacencyList.size()) {
 40	            throw new IllegalArgumentException("Vertex out of range: " + vertex);
 41	        }
 42	    }
 43	}
