 86	class BreadthFirstSearch {
 87	    public static void main(String[] args) {
 88	        Graph graph = buildSampleGraph();
 89	        List<Integer> traversalOrder = BreadthFirstTraversal.traverse(graph);
 90	
 91	        printTraversal(traversalOrder);
 92	    }
 93	
 94	    private static Graph buildSampleGraph() {
 95	        Graph graph = new Graph(6);
 96	        graph.addUndirectedEdge(1, 2);
 97	        graph.addUndirectedEdge(2, 0);
 98	        graph.addUndirectedEdge(0, 3);
 99	        graph.addUndirectedEdge(4, 5);
100	        return graph;
101	    }
102	
103	    private static void printTraversal(List<Integer> traversalOrder) {
104	        for (int vertex : traversalOrder) {
105	            System.out.print(vertex + " ");
106	        }
107	    }
108	}
